/* External numerical comparison: a transparent implementation check, never field validation. */
(() => {
  const host=document.querySelector('#mod-evaluation'); if(!host)return;
  const zh=()=>document.documentElement.lang==='zh-Hant';
  const copy=()=>zh()?{
    title:'外部模型交叉驗算',lead:'比較 HEC-HMS 或 SWMM 的已執行結果與目前 Software I 路由結果。兩者必須使用相同入流、初始水位、蓄水量—水位關係、出口定律、係數與時間設定。此功能屬數值／實作交叉驗算，並非現地驗證。',source:'外部模型',basis:'比較尺度',raw:'直接工程單位（秒、m³/s、m、m³）',scaled:'實驗室時間尺度基準（模型分鐘與縮放流量；尺度 = 240）',interval:'外部模型輸出時間間隔',second:'秒',minute:'模型分鐘',file:'匯入 CSV 結果檔',run:'比較外部結果',download:'下載四組交叉驗算基準包',
    format:'必要欄位：time_s（或 time／t；尺度模式則 model_time_min）與 outflow_m3_s（或 qout／qo；尺度模式則 scaled_outflow_m3_s）。可選：relative_head_m（或 h／stage）、incremental_storage_m3（或 s／storage）及 inflow_m3_s（或 qin／qi）。第一列必須為欄名。',guide:'基準包包含四組公開教學案例、相同物理條件的 HEC-HMS／SWMM 輸入表，以及 Software I 參考結果；不含176組固定實驗回歸資料。',missing:'請先執行 Software I 路由，並匯入有效 CSV 檔。',invalid:'CSV 至少須有兩筆時間遞增、可辨識的出流資料，且須涵蓋完整 Software I 比較期間。',failed:'比較未完成：',result:'交叉驗算結果',pass:'通過預先宣告的數值一致性門檻',warn:'未通過預先宣告的數值一致性門檻',records:'比較筆數',rmse:'出流 RMSE',mae:'出流 MAE',nse:'出流 NSE',q:'出流尖峰相對誤差',time:'出流尖峰時間差',volume:'總出流體積相對誤差',h:'最大水位相對誤差',s:'最大蓄水量相對誤差',balance:'外部模型連續方程殘差',na:'未提供',downloadRecord:'下載交叉驗算紀錄',note:'此為本研究預先宣告的數值一致性門檻：出流尖峰與最大蓄水量相對誤差均 ≤ 0.5%，且尖峰時間差不超過所填輸出時間間隔。RMSE、MAE、NSE、體積差與連續方程殘差一併呈現，但不單獨決定通過／未通過。通過僅表示此組輸入與外部執行結果在比較尺度上相符；不取代實驗室或現地驗證。'
  }:{
    title:'External-model cross check',lead:'Compare an executed HEC-HMS or SWMM result with the current Software I routing result. Both runs must use the same inflow, initial level, storage–level relation, outlet law, coefficients and time settings. This is a numerical / implementation cross check, not field validation.',source:'External model',basis:'Comparison basis',raw:'Direct engineering units (s, m³/s, m, m³)',scaled:'Laboratory time-scaled benchmark (model minutes and scaled discharge; scale = 240)',interval:'External-model reporting interval',second:'s',minute:'model min',file:'Import result CSV',run:'Compare external result',download:'Download four cross-check benchmarks',
    format:'Required columns: time_s (or time/t; model_time_min in scaled mode) and outflow_m3_s (or qout/qo; scaled_outflow_m3_s in scaled mode). Optional: relative_head_m (or h/stage), incremental_storage_m3 (or s/storage), and inflow_m3_s (or qin/qi). The first row must be headers.',guide:'The package contains four public teaching benchmarks, matched HEC-HMS/SWMM input tables, and Software I reference results; it does not contain the 176 fixed laboratory regression cases.',missing:'Run Software I first and import a valid CSV file.',invalid:'The CSV needs at least two increasing-time rows with recognized outflow and must cover the complete Software I comparison duration.',failed:'Comparison did not complete: ',result:'Cross-check result',pass:'Predeclared numerical-consistency criterion passed',warn:'Predeclared numerical-consistency criterion not passed',records:'Records compared',rmse:'Outflow RMSE',mae:'Outflow MAE',nse:'Outflow NSE',q:'Peak-outflow relative error',time:'Peak-outflow time difference',volume:'Total-outflow volume error',h:'Maximum-level relative error',s:'Maximum-storage relative error',balance:'External continuity residual',na:'not supplied',downloadRecord:'Download cross-check record',note:'This is the study’s predeclared numerical-consistency criterion: relative errors of peak outflow and maximum storage ≤ 0.5%, and peak-time difference no larger than the entered reporting interval. RMSE, MAE, NSE, volume difference and continuity residual are reported but do not independently determine pass/fail. A pass means only that this input set agrees with the external execution at the comparison scale; it does not replace laboratory or field validation.'
  };
  const box=document.createElement('section'); box.className='chart'; box.id='crossModelBox'; host.appendChild(box);
  const column=(row,names)=>names.find(k=>Object.hasOwn(row,k)); const n=v=>Number(String(v??'').trim());
  const peak=(rows,key)=>rows.reduce((best,row)=>row[key]>best[key]?row:best,rows[0]); const percent=(a,b)=>100*Math.abs(a-b)/Math.max(Math.abs(a),1e-12);
  const integrate=(rows,key)=>rows.slice(1).reduce((sum,row,i)=>sum+(row[key]+rows[i][key])*(row.t-rows[i].t)/2,0);
  const interpolate=(rows,time,key)=>{for(let i=1;i<rows.length;i++)if(time<=rows[i].t){const a=rows[i-1],b=rows[i],r=(time-a.t)/(b.t-a.t);return a[key]+r*(b[key]-a[key]);}return rows.at(-1)[key];};
  const load=file=>file.text().then(raw=>{const lines=raw.replace(/^\uFEFF/,'').trim().split(/\r?\n/).filter(Boolean),sep=lines[0]?.includes('\t')?'\t':',';if(lines.length<3)throw Error(copy().invalid);const heads=lines[0].split(sep).map(x=>x.trim().toLowerCase());return lines.slice(1).map(line=>Object.fromEntries(heads.map((h,i)=>[h,line.split(sep)[i]])));});
  function render(){const t=copy();box.innerHTML=`<h3>${t.title}</h3><p class="meta">${t.lead}</p><div class="twocol"><div><label>${t.source}</label><select id="crossSource"><option>HEC-HMS</option><option>SWMM</option></select></div><div><label>${t.basis}</label><select id="crossScale"><option value="raw">${t.raw}</option><option value="scaled">${t.scaled}</option></select></div></div><label>${t.interval} <span id="crossIntervalUnit">${t.second}</span></label><input id="crossInterval" type="number" min="0.001" step="0.001" value="60"><label>${t.file}</label><input id="crossFile" type="file" accept=".csv,.txt,text/csv,text/plain"><p class="meta">${t.format}</p><p class="meta">${t.guide} <a href="cross-model-benchmarks.zip" download>${t.download}</a></p><button class="report" id="crossRun">${t.run}</button><div class="status hide" id="crossOut"></div>`;box.querySelector('#crossRun').addEventListener('click',compare);box.querySelector('#crossScale').addEventListener('change',e=>{const scaled=e.target.value==='scaled';box.querySelector('#crossInterval').value=scaled?'1':'60';box.querySelector('#crossIntervalUnit').textContent=scaled?t.minute:t.second;});}
  function download(result){const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([JSON.stringify(result,null,2)],{type:'application/json;charset=utf-8'}));link.download='detention-pond-cross-check-record.json';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),0);}
  async function compare(){const t=copy(),out=box.querySelector('#crossOut'),file=box.querySelector('#crossFile').files[0];try{if(!last||!file)throw Error(t.missing);const scaled=box.querySelector('#crossScale').value==='scaled',interval=n(box.querySelector('#crossInterval').value);if(!(interval>0))throw Error(t.invalid);const rows=await load(file),first=rows[0],tk=column(first,scaled?['model_time_min','time_min','time']:['time_s','time','t']),qk=column(first,scaled?['scaled_outflow_m3_s','outflow_m3_s','qout','qo']:['outflow_m3_s','qout','qo','outflow']),hk=column(first,['relative_head_m','h','stage','water_level_m']),sk=column(first,['incremental_storage_m3','s','storage','storage_m3']),ik=column(first,scaled?['scaled_inflow_m3_s','inflow_m3_s','qin','qi']:['inflow_m3_s','qin','qi','inflow']);if(!tk||!qk)throw Error(t.invalid);const ext=rows.map(row=>({t:scaled?n(row[tk])*15:n(row[tk]),qo:scaled?n(row[qk])*240:n(row[qk]),h:hk?n(row[hk]):null,s:sk?n(row[sk]):null,qi:ik?(scaled?n(row[ik])*240:n(row[ik])):null})).filter(row=>Number.isFinite(row.t)&&Number.isFinite(row.qo)),ref=last.r.rows;if(ext.length<2||ext.some((row,i)=>i&&row.t<=ext[i-1].t)||ext[0].t>ref[0].t||ext.at(-1).t<ref.at(-1).t)throw Error(t.invalid);const fitted=ref.map(row=>({t:row.t,qo:interpolate(ext,row.t,'qo')})),errors=fitted.map((row,i)=>row.qo-ref[i].qo),mean=ref.reduce((sum,row)=>sum+row.qo,0)/ref.length,rmse=Math.sqrt(errors.reduce((sum,v)=>sum+v*v,0)/errors.length),mae=errors.reduce((sum,v)=>sum+Math.abs(v),0)/errors.length,denom=ref.reduce((sum,row)=>sum+(row.qo-mean)**2,0),nse=denom?1-errors.reduce((sum,v)=>sum+v*v,0)/denom:null,pr=peak(ref,'qo'),pe=peak(ext,'qo'),qError=percent(pr.qo,pe.qo),timeError=Math.abs(pr.t-pe.t),volumeError=percent(integrate(ref,'qo'),integrate(fitted,'qo')),hasH=hk&&ext.every(row=>Number.isFinite(row.h)),hasS=sk&&ext.every(row=>Number.isFinite(row.s)),relativeH=hk==='relative_head_m',relativeS=sk==='incremental_storage_m3',hError=hasH?percent(peak(ref,'h').h-(relativeH?ref[0].h:0),peak(ext,'h').h):null,sError=hasS?percent(peak(ref,'s').s-(relativeS?ref[0].s:0),peak(ext,'s').s):null,hasInflow=ik&&ext.every(row=>Number.isFinite(row.qi)),continuity=hasInflow&&hasS?integrate(ext,'qi')-integrate(ext,'qo')-(ext.at(-1).s-ext[0].s):null,threshold=scaled?interval*15:interval,pass=qError<=.5&&timeError<=threshold&&(sError===null||sError<=.5),result={model:box.querySelector('#crossSource').value,basis:scaled?'laboratory_time_scaled_240':'direct_engineering_units',external_reporting_interval:interval,external_reporting_interval_unit:scaled?'model_min':'s',records_compared:ref.length,outflow_rmse_m3_s:rmse,outflow_mae_m3_s:mae,outflow_nse:nse,peak_outflow_error_percent:qError,peak_time_error_s:timeError,total_outflow_volume_error_percent:volumeError,maximum_head_error_percent:hError,maximum_storage_error_percent:sError,external_continuity_residual_m3:continuity,pass},value=(v,u='%')=>v===null?t.na:v.toFixed(3)+u;out.className='status '+(pass?'':'warn');out.innerHTML=`<strong>${t.result} — ${pass?t.pass:t.warn}</strong><table class="metrics"><tr><th>${t.records}</th><td>${result.records_compared}</td></tr><tr><th>${t.rmse}</th><td>${value(rmse,' m³/s')}</td></tr><tr><th>${t.mae}</th><td>${value(mae,' m³/s')}</td></tr><tr><th>${t.nse}</th><td>${nse===null?t.na:nse.toFixed(5)}</td></tr><tr><th>${t.q}</th><td>${value(qError)}</td></tr><tr><th>${t.time}</th><td>${timeError.toFixed(2)} s</td></tr><tr><th>${t.volume}</th><td>${value(volumeError)}</td></tr><tr><th>${t.h}</th><td>${value(hError)}</td></tr><tr><th>${t.s}</th><td>${value(sError)}</td></tr><tr><th>${t.balance}</th><td>${value(continuity,' m³')}</td></tr></table><p class="meta">${t.note}</p><button class="report" id="crossDownload">${t.downloadRecord}</button>`;out.querySelector('#crossDownload').addEventListener('click',()=>download(result));}catch(error){out.className='status stop';out.innerHTML='<strong>'+t.failed+'</strong>'+error.message;}}
  render();document.getElementById('lang')?.addEventListener('click',()=>setTimeout(render,0));
})();
